public class Emote { public string Name,Url; }
public static class Protocol {
 public static JavaScriptSerializer Json = new JavaScriptSerializer { MaxJsonLength = 1048576 };
 public static object Get(object o, string path) { foreach(var k in path.Split('.')) { var d=o as Dictionary<string,object>; if(d==null || !d.TryGetValue(k,out o)) return null; } return o; }
 public static object[] Items(object value){var list=value as System.Collections.IList;return list==null?null:list.Cast<object>().ToArray();}
 public static string Pick(object o, params string[] paths) { foreach(var p in paths) { var v=Get(o,p); if(v!=null && !(v is Dictionary<string,object>) && !(v is System.Collections.IList) && v.ToString()!="") return v.ToString(); } return ""; }
 public static bool Supported(string source,string type) {
  if(!new[]{"twitch","youtube","kick","streamlabs","streamelements","kofi"}.Contains(source.ToLowerInvariant())) return false;
  return new[]{"Follow","Sub","ReSub","GiftSub","GiftBomb","Cheer","Raid","Subscription","Resubscription","GiftSubscription","MassGiftSubscription","KicksGifted","SuperChat","SuperSticker","NewSponsor","NewSubscriber","MemberMileStone","MembershipGift","GiftMembershipReceived","JewelsGifted","Donation","Tip","CharityDonation"}.Contains(type);
 }
 public static Alert Parse(object root) {
  string s=Pick(root,"event.source"), t=Pick(root,"event.type"); if(!Supported(s,t)) return null;
  object d=Get(root,"data");
  string name=Pick(d,"targetUser.name","targetUser.login","user.name","user.displayName","from.name","gifter.name","sender.name","donation.name","name","displayName","userName","username","user.login");
  if(Pick(d,"anonymous","isAnonymous").Equals("true",StringComparison.OrdinalIgnoreCase)) name="Anonymous";
  if(name=="") name="Viewer";
  string amount=Pick(d,"amountFormatted","formattedAmount","amount","decimalAmount","donation.amount"), currency=Pick(d,"currency","currencyCode","donation.currency");
  string detail=Pick(d,"text","message.text","message","comment","donation.message");
  string bits=Pick(d,"bits"), count=Pick(d,"gifts","count","giftCount","months","cumulativeMonths","duration","viewers");
  if(bits!="") detail=bits+" bits  "+detail;
  if(amount!="") detail=amount+" "+currency+"  "+detail;
  if(count!="") detail="Count: "+count+"  "+detail;
  DateTimeOffset stamp; if(!DateTimeOffset.TryParse(Pick(root,"timeStamp","timestamp"),out stamp)) stamp=DateTimeOffset.Now;
  return new Alert {Time=stamp.ToLocalTime().ToString("yyyy-MM-dd HH:mm:ss"),Platform=s,Kind=t,Name=name,Detail=detail.Trim(),Demo=Pick(d,"isTest","meta.isTest").Equals("true",StringComparison.OrdinalIgnoreCase),Emotes=ReadEmotes(d)};
 }
 public static List<Emote> ReadEmotes(object data){var result=new List<Emote>();string message=Pick(data,"text","message.text","message","comment");foreach(string path in new[]{"emotes","cheerEmotes","message.emotes","parts","message.parts"}){var items=Items(Get(data,path));if(items==null)continue;foreach(var item in items){string url=Pick(item,"ImageUrl","imageUrl","url","emote.imageUrl","cheermote.imageUrl"),name=Pick(item,"Name","name","text","code");int start,end;if(name==""&&int.TryParse(Pick(item,"StartIndex","startIndex"),out start)&&int.TryParse(Pick(item,"EndIndex","endIndex"),out end)&&start>=0&&end>=start&&end<message.Length)name=message.Substring(start,end-start+1);if(url.StartsWith("//"))url="https:"+url;if(url==""){string id=Pick(item,"id","Id","emote.id"),source=Pick(item,"source","Source");if(System.Text.RegularExpressions.Regex.IsMatch(id,"^(?:[0-9]+|emotesv2_[a-fA-F0-9]+)$")&&(source==""||source.Equals("twitch",StringComparison.OrdinalIgnoreCase)))url="https://static-cdn.jtvnw.net/emoticons/v2/"+id+"/default/dark/2.0";}if(url==""||name==""||result.Any(x=>x.Url==url&&x.Name==name))continue;result.Add(new Emote{Name=name,Url=url});if(result.Count==128)return result;}}return result;}
 public static string Hash(string s) { using(var h=SHA256.Create()) return Convert.ToBase64String(h.ComputeHash(Encoding.UTF8.GetBytes(s))); }
}
public static class Theme {
 public static readonly Color Canvas=Color.FromArgb(22,15,37);
 public static readonly Color Surface=Color.FromArgb(37,25,55);
 public static readonly Color Raised=Color.FromArgb(61,41,86);
 public static readonly Color Text=Color.FromArgb(247,240,255);
 public static readonly Color Muted=Color.FromArgb(185,169,205);
 public static readonly Color Accent=Color.FromArgb(200,163,255);
 public static void Round(Control c,int radius) {c.Resize+=delegate{if(c.Width<radius||c.Height<radius)return;using(var path=new System.Drawing.Drawing2D.GraphicsPath()){int d=radius;path.AddArc(0,0,d,d,180,90);path.AddArc(c.Width-d,0,d,d,270,90);path.AddArc(c.Width-d,c.Height-d,d,d,0,90);path.AddArc(0,c.Height-d,d,d,90,90);path.CloseFigure();var old=c.Region;c.Region=new Region(path);if(old!=null)old.Dispose();}};}
}
public class ModernButton : Button {
 public bool Primary;
 bool hovered,pressed;
 public ModernButton(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);UseVisualStyleBackColor=false;}
 protected override void OnPaintBackground(PaintEventArgs e){e.Graphics.Clear(Parent==null?Theme.Canvas:Parent.BackColor);}
 protected override void OnMouseEnter(EventArgs e){base.OnMouseEnter(e);hovered=true;Invalidate();}
 protected override void OnMouseLeave(EventArgs e){base.OnMouseLeave(e);hovered=false;pressed=false;Invalidate();}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left)pressed=true;Invalidate();}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);pressed=false;Invalidate();}
 protected override void OnGotFocus(EventArgs e){base.OnGotFocus(e);Invalidate();}
 protected override void OnLostFocus(EventArgs e){base.OnLostFocus(e);pressed=false;Invalidate();}
 protected override void OnPaint(PaintEventArgs e) {
  e.Graphics.Clear(Parent==null?Theme.Canvas:Parent.BackColor);
  e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
  var r=new Rectangle(1,1,Width-3,Height-3);int radius=18;
  using(var p=new System.Drawing.Drawing2D.GraphicsPath()){
   p.AddArc(r.X,r.Y,radius,radius,180,90);p.AddArc(r.Right-radius,r.Y,radius,radius,270,90);p.AddArc(r.Right-radius,r.Bottom-radius,radius,radius,0,90);p.AddArc(r.X,r.Bottom-radius,radius,radius,90,90);p.CloseFigure();
   using(var b=new SolidBrush(Enabled&&!pressed?BackColor:Theme.Surface))e.Graphics.FillPath(b,p);
   if(Focused||Primary||hovered)using(var pen=new Pen(Theme.Accent,Focused?2:1))e.Graphics.DrawPath(pen,p);
  }
  TextRenderer.DrawText(e.Graphics,Text,Font,r,Enabled?ForeColor:Color.Gray,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);
 }
}
