 void ShowSetup(){using(var w=new Form{Text="Let's get you connected",Size=new Size(780,630),MinimumSize=new Size(700,580),StartPosition=FormStartPosition.CenterParent,BackColor=bg,ForeColor=Color.White,Font=Font}){
  string[] titles={"Welcome to your new alert feed","Connect Twitch","Add your Streamlabs tips","Add YouTube and Kick (optional)","Allow the app to receive alerts","You're ready to connect"};
  string[] bodies={"This app puts your stream alerts in one window.\n\nFirst, open Streamer.bot on this computer. It connects to your accounts and passes alerts to this app.\n\nYou do not need to create actions, triggers or individual events. We take care of selecting the alerts.\n\nAlready connected your accounts? Skip ahead to step 5.","In Streamer.bot:\n\n1. Open Platforms > Twitch > Accounts.\n2. Click Login for the Broadcaster Account.\n3. Sign in with the Twitch account you stream from.\n4. Complete the permissions screen.\n\nYou do not need a separate bot account for this app.\nSkip this step if you don't use Twitch.","On the Streamlabs website:\n1. Open Settings > API Settings > API Tokens.\n2. Copy Your Socket API Token.\n\nIn Streamer.bot:\n3. Open Integrations > Streamlabs.\n4. Paste the token and click Connect to Streamlabs.\n5. Turn on Auto Connect and Auto Reconnect.\n\nUse Streamlabs, not Streamlabs Desktop. Keep the token private.","YouTube\nOpen Platforms > YouTube and sign into your channel. In Broadcasts, right-click your live stream and choose Monitor.\n\nKick\nSign into Streamer.bot at the bottom-left of its window. Then sign into Platforms > Kick.\n\nAlso sign into the Streamer.bot website and connect the same Kick account under Account Settings > Connections. Kick needs BOTH connections.\n\nSkip any platforms you don't use.","In Streamer.bot:\n\n1. Open Servers / Clients > WebSocket Server.\n2. Set the address to 127.0.0.1 and the port to 8080.\n3. Turn on Auto-Start, then start the server.\n4. If you set a password here, enter it in this app's Connection settings.\n\nThis is a local server password, not your Twitch or Streamlabs password. Leave it blank if you haven't set one.","Click Finish, then Accounts > Connect bridge.\n\nKeep Streamer.bot open. Once connected, new alerts will appear automatically.\n\nTry Try a preview to explore the feed without connecting or spending any money. Samples are clearly marked.\n\nSetup steps are instructions, not a check of your account connections. Check each account in Streamer.bot if alerts are missing."};
  int page=0;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(28),ColumnCount=1,RowCount=4};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,32));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,62));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));w.Controls.Add(layout);
  var progress=Label("",10,accent,true);var title=Label("",22,Color.White,true);var body=new RichTextBox{Dock=DockStyle.Fill,ReadOnly=true,BorderStyle=BorderStyle.None,BackColor=bg,ForeColor=Color.White,Font=new Font("Segoe UI",12),TabStop=false};layout.Controls.Add(progress,0,0);layout.Controls.Add(title,0,1);layout.Controls.Add(body,0,2);
  var nav=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(nav,0,3);var back=Button("Back",delegate{});var next=Button("Next",delegate{},true);nav.Controls.Add(back);nav.Controls.Add(next);nav.Controls.Add(Button("Connection settings",delegate{ShowSettings();}));nav.Controls.Add(Button("Full guide",delegate{ShowGuide();}));
