 void ShowGuide(){using(var guide=new Form{Text="Setup guide",Size=new Size(820,680),StartPosition=FormStartPosition.CenterParent,BackColor=bg}){var text=new RichTextBox{Dock=DockStyle.Fill,ReadOnly=true,BackColor=panel,ForeColor=Color.White,Font=new Font("Segoe UI",11),BorderStyle=BorderStyle.None,DetectUrls=true};try{text.Text=File.ReadAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"START-HERE.txt"));}catch(IOException){text.Text="The guide is missing. Extract the whole ZIP, or use Account setup for step-by-step instructions.";}text.LinkClicked+=delegate(object sender,LinkClickedEventArgs e){Uri link;if(Uri.TryCreate(e.LinkText,UriKind.Absolute,out link)&&link.Scheme=="https")System.Diagnostics.Process.Start(link.AbsoluteUri);};guide.Padding=new Padding(20);guide.Controls.Add(text);guide.ShowDialog(this);}}
 static string Friendly(string kind){switch(kind){case "Follow":return "New follower";case "Sub":case "Subscription":return "New subscriber";case "ReSub":case "Resubscription":return "Resubscribed";case "GiftSub":case "GiftSubscription":return "Gifted subscription";case "GiftBomb":case "MassGiftSubscription":return "Gifted subscriptions";case "Cheer":return "Sent bits";case "NewSponsor":return "New member";case "NewSubscriber":return "New subscriber";case "SuperChat":return "Super Chat";case "SuperSticker":return "Super Sticker";case "MemberMileStone":return "Member milestone";case "MembershipGift":return "Gifted memberships";case "GiftMembershipReceived":return "Received membership";case "Donation":case "Tip":return "Sent a tip";case "KicksGifted":return "Sent Kicks";case "JewelsGifted":return "Sent Jewels";case "CharityDonation":return "Charity donation";default:return kind;}}
 void RefreshFeed(){feed.BeginUpdate();feed.Items.Clear();string query=search.Text.ToLowerInvariant();foreach(var a in alerts){string friendly=Friendly(a.Kind);if(filter.SelectedIndex>0&&!a.Platform.Equals(filter.Text,StringComparison.OrdinalIgnoreCase))continue;if(!(a.Name+" "+a.Kind+" "+friendly+" "+a.Detail).ToLowerInvariant().Contains(query))continue;string time=a.Time.Length>=19?a.Time.Substring(11):a.Time;var row=new ListViewItem(new[]{time,a.Platform,(a.Demo?"Sample · ":"")+friendly,a.Name,a.Detail});row.Tag=a;row.ForeColor=a.Platform.Equals("Twitch",StringComparison.OrdinalIgnoreCase)?Color.FromArgb(202,173,255):a.Platform.Equals("Kick",StringComparison.OrdinalIgnoreCase)?Color.FromArgb(151,231,137):a.Platform.Equals("YouTube",StringComparison.OrdinalIgnoreCase)?Color.FromArgb(255,164,167):accent;feed.Items.Add(row);}feed.EndUpdate();empty.Visible=feed.Items.Count==0;empty.Text=alerts.Count==0?"Your next great moment starts here\n\nOpen Connections to sign in, or try sample alerts.":"No matching alerts\n\nTry another platform or clear your search.";summary.Text=alerts.Count==0?"Activity feed":alerts.Count(a=>!a.Demo)+" alerts   ·   "+alerts.Count(a=>a.Demo)+" samples";totals.Text=feed.Items.Count+" shown · Newest first · Double-click for details\nHistory: "+(preferences.Retention==0?"not saved":preferences.Retention+" days")+" · Latest 2,000 alerts.";}
