 void NotifyDesktop(Alert alert){if(alert.Runs.Count==0)PrepareMessage(alert);PlayEventSound(alert);if(ShowEventPopup(alert)&&popup!=null)popup.Present(alert,Friendly(alert.Kind),emoteCache,Screen.FromControl(this).WorkingArea); }
 void PrepareMessage(Alert a){a.Runs=InlineMessage.Resolve(a,sevenTv);foreach(string url in a.Runs.Where(r=>r.Url!=null).Select(r=>r.Url).Distinct().Take(128)){var pending=emoteCache.Load(url,delegate{if(!IsDisposed){feed.Invalidate();if(chatList!=null)chatList.Invalidate();if(popup!=null)popup.RefreshEmotes(a,emoteCache);}});}}
 async Task ReloadSevenTv(){await sevenTv.Refresh("twitch",detectedChannel,emoteSetOverride,delegate{if(IsDisposed)return;foreach(var a in alerts.Take(200))PrepareMessage(a);feed.Invalidate();});}
 void ShowSevenTv(){using(var w=new Form{Text="Twitch & 7TV emotes",Size=new Size(760,460),MinimumSize=new Size(760,460),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Canvas,ForeColor=Theme.Text,Font=Font}){
