 void ShowSelectedAlert(){if(feed.SelectedItems.Count==0)return;var a=(Alert)feed.SelectedItems[0].Tag;using(var w=new Form{Text="Alert details",Size=new Size(720,440),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Canvas,ForeColor=Theme.Text,Font=Font}){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=3};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,68));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,44));w.Controls.Add(layout);layout.Controls.Add(Label(a.Name+" — "+Friendly(a.Kind)+"\n"+a.Platform+" · "+a.Time+(a.Demo?" · Sample":""),12,Theme.Text,true),0,0);var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Theme.Surface};var body=new MessageView{Alert=a,Cache=emoteCache,Font=Font,Location=new Point(10,10),Width=620,Height=Math.Min(16000,Math.Max(100,a.Detail.Length*32/35+64))};scroll.Controls.Add(body);scroll.Resize+=delegate{body.Width=Math.Max(100,scroll.ClientSize.Width-36);};layout.Controls.Add(scroll,0,1);var footer=new FlowLayoutPanel{Dock=DockStyle.Fill};footer.Controls.Add(Button("Copy message",delegate{Clipboard.SetText(a.Detail==""?" ":a.Detail);}));footer.Controls.Add(Button("Emote status",delegate{var lines=a.Runs.Where(r=>r.Url!=null).Select(r=>r.Text+": "+emoteCache.Describe(r.Url)).Distinct().ToArray();MessageBox.Show(w,(lines.Length==0?"No matching image data was received for this message.":string.Join("\n",lines))+"\n\n"+sevenTv.TwitchStatus+"\n"+sevenTv.Status,"Emote status");}));layout.Controls.Add(footer,0,2);w.ShowDialog(this);}}
 void Add(Alert a){if(a==null)return;if(a.Kind=="Chat"){AddChat(a);return;}alerts.Insert(0,a);RecordArrival(a);if(!a.Demo&&!previewing)RunTools(Category(a.Kind),new{source="UniversalStream Assist",platform=a.Platform,eventType=a.Kind,viewer=a.Name,message=a.Detail});if(alerts.Count>2000)alerts.RemoveAt(2000);PrepareMessage(a);RefreshFeed();if(!previewing)NotifyDesktop(a);}
 void Samples(){previewing=true;try{alerts.RemoveAll(a=>a.Demo);string[] sources={"Twitch","Twitch","YouTube","Kick","Streamlabs"},types={"Follow","Cheer","SuperChat","Subscription","Donation"};for(int i=0;i<sources.Length;i++)Add(new Alert{Time=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),Platform=sources[i],Kind=types[i],Name=new[]{"LunarFox","PixelPilot","NovaPlays","NightOwl","CozyViewer"}[i],Detail=new[]{"Welcome to the community!","500 bits","5.00 GBP — Great stream!","New subscriber","10.00 GBP — Thank you!"}[i],Demo=true});}finally{previewing=false;}var sample=alerts.FirstOrDefault(a=>a.Demo);if(sample!=null)NotifyDesktop(sample);}
 void Export(){using(var dialog=new SaveFileDialog{Filter="JSON file|*.json",FileName="stream-alerts.json"})if(dialog.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(dialog.FileName,Protocol.Json.Serialize(alerts),Encoding.UTF8);}catch(Exception){MessageBox.Show(this,"Could not save that file. Please choose another folder.","Could not save alerts");}}

 async Task Send(ClientWebSocket ws,object request,CancellationToken ct) {byte[] bytes=Encoding.UTF8.GetBytes(Protocol.Json.Serialize(request));await ws.SendAsync(new ArraySegment<byte>(bytes),WebSocketMessageType.Text,true,ct);}
 async Task<Dictionary<string,object>> Receive(ClientWebSocket ws,CancellationToken ct) {using(var m=new MemoryStream()){var b=new byte[8192];WebSocketReceiveResult r;do{r=await ws.ReceiveAsync(new ArraySegment<byte>(b),ct);if(r.MessageType==WebSocketMessageType.Close)throw new IOException("Bridge closed");if(r.MessageType!=WebSocketMessageType.Text)throw new IOException("Unexpected message");m.Write(b,0,r.Count);if(m.Length>1048576)throw new IOException("Message too large");}while(!r.EndOfMessage);return Protocol.Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(m.ToArray()));}}
 async Task Run(Uri uri,string secret,CancellationToken ct) {
  while(!ct.IsCancellationRequested) {
   try {using(var ws=new ClientWebSocket()) {using(var handshake=CancellationTokenSource.CreateLinkedTokenSource(ct)) {handshake.CancelAfter(15000);status.Text="Connecting to Streamer.bot…";await ws.ConnectAsync(uri,handshake.Token);var hello=await Receive(ws,handshake.Token);if(Protocol.Pick(hello,"request")!="Hello")throw new IOException("Missing greeting");if(Protocol.Get(hello,"authentication")!=null){await Send(ws,new{request="Authenticate",id="auth",authentication=Protocol.Hash(Protocol.Hash(secret+Protocol.Pick(hello,"authentication.salt"))+Protocol.Pick(hello,"authentication.challenge"))},handshake.Token);var auth=await Receive(ws,handshake.Token);if(Protocol.Pick(auth,"status")!="ok"){status.Text="Password rejected. Open Connection settings and enter the password from Streamer.bot > WebSocket Server.";return;}}
    await Send(ws,new{request="GetEvents",id="catalog"},handshake.Token);var catalog=await Receive(ws,handshake.Token);var available=Protocol.Get(catalog,"events") as Dictionary<string,object>;if(available==null)throw new IOException("No event catalog");var selected=new Dictionary<string,List<string>>();foreach(var group in available){var names=group.Value as System.Collections.IEnumerable;if(names==null)continue;foreach(var n in names){if(Protocol.Supported(group.Key,n.ToString())||(group.Key=="Twitch"&&n.ToString()=="ChatMessage")){if(!selected.ContainsKey(group.Key))selected[group.Key]=new List<string>();selected[group.Key].Add(n.ToString());}}}if(selected.Count==0)throw new IOException("No supported events");await Send(ws,new{request="Subscribe",id="subscribe",events=selected},handshake.Token);
    bool accepted=false;while(!accepted){var ack=await Receive(ws,handshake.Token);if(Protocol.Pick(ack,"id")=="subscribe"){if(Protocol.Pick(ack,"status")!="ok")throw new IOException("Subscription rejected");accepted=true;}}await Send(ws,new{request="GetBroadcaster",id="notify-broadcaster"},ct);await Send(ws,new{request="TwitchGetEmotes",id="notify-twitch-emotes"},ct);status.Text="Listening for new alerts. Keep Streamer.bot open. Check your account connections there if an alert is missing.";
   }
   while(!ct.IsCancellationRequested){var message=await Receive(ws,ct);if(Protocol.Pick(message,"id")=="notify-twitch-emotes"){sevenTv.ImportTwitch(message);foreach(var prior in alerts.Take(200))PrepareMessage(prior);continue;}if(Protocol.Pick(message,"id")=="notify-broadcaster"){string broadcasterId=Protocol.Pick(message,"platforms.twitch.broadcastUserId");if(broadcasterId!=""&&broadcasterId!=detectedChannel){detectedChannel=broadcasterId;var refresh=ReloadSevenTv();}continue;}if(Protocol.Pick(message,"event.source")=="Twitch"&&sevenTv.LearnTwitch(Protocol.ReadEmotes(Protocol.Get(message,"data")))){foreach(var prior in alerts.Take(200))PrepareMessage(prior);feed.Invalidate();}var alert=Protocol.Parse(message);if(alert==null||((twitchStop!=null&&alert.Platform=="Twitch")||(streamlabsStop!=null&&alert.Platform=="Streamlabs")||(youtubeStop!=null&&alert.Platform=="YouTube")||(kickStop!=null&&alert.Platform=="Kick")))continue;string id=Protocol.Pick(message,"data.messageId","data.eventId");if(id!=""){string key=alert.Platform+":"+alert.Kind+":"+id;if(!seen.Add(key))continue;seenOrder.Enqueue(key);if(seenOrder.Count>4000)seen.Remove(seenOrder.Dequeue());}Add(alert);}
  }}catch(OperationCanceledException){if(ct.IsCancellationRequested)break;status.Text="Connection timed out. Retrying in 5 seconds…";}catch(Exception){status.Text="Cannot reach Streamer.bot. Open it and start its WebSocket Server (setup step 5). Trying again in 5 seconds…";}
  try{await Task.Delay(5000,ct);}catch(OperationCanceledException){break;}
  }
  status.Text="Disconnected. Click Connect when you are ready. Alerts received while disconnected will not appear here.";
 }
